/**
 * Horizontal counterpart of Stack for control rows, meta lines and action groups (`design/components/inline.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/inline.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'
import { Dynamic } from 'solid-js/web'

import {
  claimSlot,
  classes,
  mergeParts,
  scope,
  spacingAttrs,
  type Defaults,
  type LayoutPatch,
  type SpaceStep,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/layout/layout.module.css'

export type InlineAlign = NonNullable<InlineProps['align']>

export type InlineElement = NonNullable<InlineProps['as']>

export type InlineJustify = NonNullable<InlineProps['justify']>

export interface InlineProps {
  align?: 'stretch' | 'start' | 'center' | 'end' | 'baseline'
  as?: 'div' | 'section' | 'ul' | 'ol' | 'nav'
  children?: JSX.Element
  gap?: SpaceStep
  justify?: 'start' | 'center' | 'end' | 'between'
  p?: SpaceStep
  patch?: LayoutPatch
  px?: SpaceStep
  py?: SpaceStep
  /**
   * Tag lists and filter rows. Row gap equals column gap.
   */
  wrap?: boolean
}

/** Horizontal counterpart of Stack for control rows, meta lines and action groups. */
export default function Inline(given: InlineProps): JSX.Element {
  const props = mergeProps(
    { align: 'center', justify: 'start', as: 'div', wrap: false } as Defaults<
      InlineProps,
      'align' | 'justify' | 'as' | 'wrap'
    >,
    claimSlot(given),
  )
  return scope(() => {
    return (
      <Dynamic
        component={props.as}
        {...mergeParts(
          spacingAttrs({
            gap: props.gap,
            p: props.p,
            px: props.px,
            py: props.py,
            patch: props.patch,
          }),
          {
            class: classes(styles.layout, styles.inline),
            'data-align': props.align,
            'data-justify': props.justify,
            'data-wrap': props.wrap ? '' : undefined,
            'data-member': 'inline',
          },
        )}
      >
        {props.children}
      </Dynamic>
    )
  })
}
